--
-- Table structure for table `game_items`
--

DROP TABLE IF EXISTS `game_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_items` (
  `game_item_id` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `game_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `team_id` int unsigned NOT NULL,
  `side` enum('team1','team2') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_id` int unsigned NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `item_slot` tinyint unsigned NOT NULL,
  `item_id` int unsigned DEFAULT NULL,
  `item_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`game_item_id`),
  UNIQUE KEY `uq_game_items_slot` (`game_id`,`player_id`,`item_slot`),
  KEY `idx_game_items_team` (`team_id`),
  KEY `idx_game_items_player` (`player_id`),
  KEY `idx_game_items_hero` (`hero_id`),
  KEY `idx_game_items_item` (`item_id`),
  CONSTRAINT `fk_game_items_game` FOREIGN KEY (`game_id`) REFERENCES `games` (`game_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_game_items_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_game_items_master_item` FOREIGN KEY (`item_id`) REFERENCES `master_items` (`item_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_game_items_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`player_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_game_items_team` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

