--
-- Table structure for table `game_players`
--

DROP TABLE IF EXISTS `game_players`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_players` (
  `player_game_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `game_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `team_id` int unsigned NOT NULL,
  `side` enum('team1','team2') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_id` int unsigned NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `kills` smallint unsigned NOT NULL DEFAULT '0',
  `deaths` smallint unsigned NOT NULL DEFAULT '0',
  `assists` smallint unsigned NOT NULL DEFAULT '0',
  `damage` decimal(15,3) NOT NULL DEFAULT '0.000',
  `damage_taken` decimal(15,3) NOT NULL DEFAULT '0.000',
  `turret_damage` decimal(15,3) NOT NULL DEFAULT '0.000',
  `gold` decimal(15,3) NOT NULL DEFAULT '0.000',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`player_game_id`),
  UNIQUE KEY `uq_game_players_game_player` (`game_id`,`player_id`),
  KEY `idx_game_players_team` (`team_id`),
  KEY `idx_game_players_player` (`player_id`),
  KEY `idx_game_players_hero` (`hero_id`),
  CONSTRAINT `fk_game_players_game` FOREIGN KEY (`game_id`) REFERENCES `games` (`game_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_game_players_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_game_players_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`player_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_game_players_team` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

