--
-- Table structure for table `games`
--

DROP TABLE IF EXISTS `games`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `games` (
  `game_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_id` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_match_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `game_number` tinyint unsigned NOT NULL,
  `team1_id` int unsigned NOT NULL,
  `team2_id` int unsigned NOT NULL,
  `winner_team_id` int unsigned DEFAULT NULL,
  `duration_seconds` int unsigned NOT NULL DEFAULT '0',
  `team1_kills` smallint unsigned NOT NULL DEFAULT '0',
  `team2_kills` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`game_id`),
  UNIQUE KEY `uq_games_match_number` (`match_id`,`game_number`),
  KEY `idx_games_source_match` (`source_match_id`),
  KEY `idx_games_team1` (`team1_id`),
  KEY `idx_games_team2` (`team2_id`),
  KEY `idx_games_winner` (`winner_team_id`),
  CONSTRAINT `fk_games_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`match_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_games_team1` FOREIGN KEY (`team1_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_games_team2` FOREIGN KEY (`team2_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_games_winner` FOREIGN KEY (`winner_team_id`) REFERENCES `teams` (`team_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

