DROP TABLE IF EXISTS `hero_attributes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_attributes` (
  `hero_id` int unsigned NOT NULL,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `offense` tinyint unsigned DEFAULT NULL,
  `durability` tinyint unsigned DEFAULT NULL,
  `control_effects` tinyint unsigned DEFAULT NULL,
  `difficulty` tinyint unsigned DEFAULT NULL,
  `hero_info_json` json DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_id`),
  KEY `idx_hero_attributes_source` (`source_hero_id`),
  CONSTRAINT `fk_hero_attributes_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
