--
-- Table structure for table `hero_build_items`
--

DROP TABLE IF EXISTS `hero_build_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_build_items` (
  `hero_build_item_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `position` smallint unsigned DEFAULT NULL,
  `item_source_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `build_count` int unsigned DEFAULT NULL,
  `total_builds` int unsigned DEFAULT NULL,
  `share_percent` decimal(8,4) DEFAULT NULL,
  `power_spike` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_build_item_id`),
  UNIQUE KEY `uq_hero_build_item_snapshot` (`source_hero_id`,`position`,`item_source_id`,`snapshot_at`),
  KEY `idx_hero_build_items_hero` (`hero_id`),
  KEY `idx_hero_build_items_item` (`item_source_id`),
  CONSTRAINT `fk_hero_build_items_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1557 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `hero_build_items`
--

LOCK TABLES `hero_build_items` WRITE;
/*!40000 ALTER TABLE `hero_build_items` DISABLE KEYS */;
