--
-- Table structure for table `hero_build_situational_swaps`
--

DROP TABLE IF EXISTS `hero_build_situational_swaps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_build_situational_swaps` (
  `hero_build_swap_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `condition_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `item_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `share_percent` decimal(8,4) DEFAULT NULL,
  `raw_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_build_swap_id`),
  KEY `idx_hero_build_swaps_hero` (`hero_id`),
  KEY `idx_hero_build_swaps_source` (`source_hero_id`),
  CONSTRAINT `fk_hero_build_swaps_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

