--
-- Table structure for table `hero_build_talents`
--

DROP TABLE IF EXISTS `hero_build_talents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_build_talents` (
  `hero_build_talent_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `position` smallint unsigned DEFAULT NULL,
  `talent_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `build_count` int unsigned DEFAULT NULL,
  `total_builds` int unsigned DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_build_talent_id`),
  UNIQUE KEY `uq_hero_build_talent_snapshot` (`source_hero_id`,`position`,`talent_name`,`snapshot_at`),
  KEY `idx_hero_build_talents_hero` (`hero_id`),
  CONSTRAINT `fk_hero_build_talents_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=775 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

