--
-- Table structure for table `hero_counters`
--

DROP TABLE IF EXISTS `hero_counters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_counters` (
  `hero_counter_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `relation_type` enum('counter','strong_against','synergy') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_hero_id` int unsigned DEFAULT NULL,
  `target_hero_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_hero_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `win_rate_advantage` decimal(8,4) DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_counter_id`),
  UNIQUE KEY `uq_hero_counter_snapshot` (`source_hero_id`,`relation_type`,`target_source_hero_id`,`snapshot_at`),
  KEY `idx_hero_counters_hero` (`hero_id`),
  KEY `idx_hero_counters_target` (`target_hero_id`),
  KEY `idx_hero_counters_relation` (`relation_type`),
  CONSTRAINT `fk_hero_counters_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_hero_counters_target` FOREIGN KEY (`target_hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7861 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `hero_counters`
--

LOCK TABLES `hero_counters` WRITE;
/*!40000 ALTER TABLE `hero_counters` DISABLE KEYS */;
