--
-- Table structure for table `hero_details`
--

DROP TABLE IF EXISTS `hero_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_details` (
  `hero_detail_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `hero_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `win_rate` decimal(8,4) DEFAULT NULL,
  `pick_rate` decimal(8,4) DEFAULT NULL,
  `ban_rate` decimal(8,4) DEFAULT NULL,
  `win_rate_epic` decimal(8,4) DEFAULT NULL,
  `win_rate_legend` decimal(8,4) DEFAULT NULL,
  `win_rate_mythic` decimal(8,4) DEFAULT NULL,
  `win_rate_mythical_honor` decimal(8,4) DEFAULT NULL,
  `win_rate_mythical_glory_plus` decimal(8,4) DEFAULT NULL,
  `offense` tinyint unsigned DEFAULT NULL,
  `durability` tinyint unsigned DEFAULT NULL,
  `control_effects` tinyint unsigned DEFAULT NULL,
  `difficulty` tinyint unsigned DEFAULT NULL,
  `hero_info_json` json DEFAULT NULL,
  `base_stats_json` json DEFAULT NULL,
  `source_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_detail_id`),
  UNIQUE KEY `uq_hero_details_snapshot` (`source_hero_id`,`snapshot_at`),
  KEY `idx_hero_details_hero` (`hero_id`),
  KEY `idx_hero_details_win_rate` (`win_rate`),
  KEY `idx_hero_details_pick_rate` (`pick_rate`),
  KEY `idx_hero_details_ban_rate` (`ban_rate`),
  CONSTRAINT `fk_hero_details_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=267 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

