--
-- Table structure for table `hero_statistics`
--

DROP TABLE IF EXISTS `hero_statistics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero_statistics` (
  `hero_statistics_id` int unsigned NOT NULL AUTO_INCREMENT,
  `source_hero_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_id` int unsigned DEFAULT NULL,
  `hero_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hero_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `source_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snapshot_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_statistics_id`),
  UNIQUE KEY `uq_hero_statistics_snapshot` (`source_hero_id`,`snapshot_at`),
  KEY `idx_hero_statistics_hero` (`hero_id`),
  KEY `idx_hero_statistics_name` (`hero_name`),
  CONSTRAINT `fk_hero_statistics_hero` FOREIGN KEY (`hero_id`) REFERENCES `heroes` (`hero_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=267 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

